import { getterTree, mutationTree, actionTree } from 'typed-vuex'
import store, { $storex } from '.'
import { v4 as uuidv4 } from 'uuid'
import { ChatSearchRequest } from '@/api/model/ChatSearchRequest'

export const namespaced = true

export const state = () => ({
  chats: {},
  activeChatId: null,
  chatEvents: {},
  searchResults: null,
})

function registerChat(state, chat) {
  if (!chat?.id) {
    console.error('[chats store] Attempted to store a null/invalid chat:', chat)
    return
  }

  if (state.chats[chat.id]) {
    // Merge while preserving messages
    state.chats[chat.id] = {
      ...state.chats[chat.id],
      ...chat,
      messages: state.chats[chat.id].messages
    }
  } else {
    state.chats[chat.id] = chat
  }
}

function getChatWorkingProject({ owner_project_id, project_id }) {
  return $storex.projects.allProjectsById[project_id || owner_project_id] ||
            $storex.projects.activeProject
}

function getChatProject({ owner_project_id }) {
  return $storex.projects.allProjectsById[owner_project_id] ||
            $storex.projects.activeProject
}

function getRootChat(state, chatId) {
  let current = state.chats?.[chatId]
  if (!current) return null
  let depth = 0
  while (current?.parent_id && state.chats?.[current.parent_id] && depth < 20) {
    current = state.chats[current.parent_id]
    depth++
  }
  return current
}

export const getters = getterTree(state, {
  allChats: state => Object.values(state.chats || {}),
  allTags: state => new Set(Object.values(state.chats || {})?.map(c => c.tags).reduce((a, b) => a.concat(b), []) || []),
  allPRs: state => Object.values(state.chats || {}).filter(c => c.pr_view?.from_branch),
  isChatUpdating: state => (chatId) => {
    return (state.chatEvents[chatId]?.updatingCount || 0) > 0
  },
  activeChat: state => state.activeChatId ? (state.chats[state.activeChatId] || null) : null,
  chatProject: state => ({ project_id, owner_project_id }) => {
    return $storex.projects.allProjectsById[project_id || owner_project_id]
  },
  chatChildren: state => (chatId) => {
    const children = Object.values(state.chats || {}).filter(c => c.parent_id === chatId)
    return children
  },
  chatDescendants: (state, getters) => (chatId) => {
    const direct = getters.chatChildren(chatId)
    const indirect = direct.flatMap(child => getters.chatDescendants(child.id))
    return [...direct, ...indirect]
  },
  rootChat: state => (chatId) => getRootChat(state, chatId),
  searchResults: state => state.searchResults,
})

export const mutations = mutationTree(state, {
  setActiveChatId(state, chatId) {
    state.activeChatId = chatId || null
  },

  clearActiveChat(state) {
    state.activeChatId = null
  },

  setSearchResults(state, results) {
    state.searchResults = results
  },

  clearSearchResults(state) {
    state.searchResults = null
  },

  setChatUpdating(state, { chatId, updating }) {
    const current = state.chatEvents[chatId]?.updatingCount || 0
    const prevTimeoutId = state.chatEvents[chatId]?.timeoutId || null

    if (prevTimeoutId) {
      clearTimeout(prevTimeoutId)
    }

    if (!updating) {
      state.chatEvents = {
        ...state.chatEvents,
        [chatId]: {
          ...(state.chatEvents[chatId] || {}),
          updatingCount: 0,
          updatingAt: null,
          timeoutId: null,
        }
      }
    } else {
      const timeoutId = setTimeout(() => {
        $storex.chats.setChatUpdating({ chatId, updating: false })
      }, 10000)

      state.chatEvents = {
        ...state.chatEvents,
        [chatId]: {
          ...(state.chatEvents[chatId] || {}),
          updatingCount: current + 1,
          updatingAt: new Date().toISOString(),
          timeoutId,
        }
      }
    }
  },

  addMessageToChat(state, { chatId, message }) {
    const chat = state.chats[chatId]
    if (!chat) return
      chat.messages = [...(chat.messages || []), message]
  },

  setChatStatus(state, { chatId, status }) {
    const chat = state.chats[chatId]
    if (chat) {
      chat.status = status
    }
  }
})

export const actions = actionTree(
  { state, getters, mutations },
  {
    async init ({ state }) {
    },
    async loadChats({ state }) {
      const chats = await $storex.api.chats.list()
      chats.forEach(chat => registerChat(state, { ...chat, status: 'uninitialized' }))
    },
    // CHANGED: Accept ChatSearchRequest or plain object
    async searchChats({ state }, options = {}) {
      let searchRequest

      // Accept ChatSearchRequest instance or plain object
      if (options instanceof ChatSearchRequest) {
        searchRequest = options
      } else {
        // Validate query before creating request
        if (!options.query || options.query.trim() === '') {
          $storex.chats.clearSearchResults()
          return null
        }
        searchRequest = new ChatSearchRequest(options)
      }

      // Validate request
      const validationErrors = searchRequest.getValidationErrors()
      if (validationErrors.length > 0) {
        console.error('[chats store] Search validation failed:', validationErrors)
        return {
          error: validationErrors[0],
          results: [],
          total: 0,
          page: 1,
          page_size: searchRequest.page_size,
          total_pages: 0,
          has_next: false,
          has_prev: false,
        }
      }

      const project = $storex.projects.activeProject
      const results = await project.$api.chats.search(searchRequest)

      $storex.chats.setSearchResults(results)
      return results
    },
    async clearChatSearch() {
      $storex.chats.clearSearchResults()
    },
    async ensureChatRoot({ state }, chat) {
      if (!chat?.id) return null
      let current = state.chats[chat.id] || {
        id: chat.id,
        owner_project_id: chat.owner_project_id,
        project_id: chat.project_id
      }
      let depth = 0
      while (current?.parent_id && depth < 20) {
        const parent = state.chats[current.parent_id]
        if (!parent) {
          const loadedParent = await $storex.chats.loadChat({
            id: current.parent_id,
            owner_project_id: current.owner_project_id || current.project_id
          })
          if (!loadedParent) break
          current = loadedParent
        } else {
          current = parent
        }
        depth++
      }
      return getRootChat(state, current.id) || current
    },
    async loadChildrenHierarchy({ state, getters }, rootChat, maxDepth = 5) {
      if (!rootChat?.id) return []

      const loadRecursive = async (parentChat, depth = 0) => {
        if (depth >= maxDepth) return []
        const children = getters.chatChildren(parentChat.id) || []
        const result = [...children]
        for (const child of children) {
          result.push(...(await loadRecursive(child, depth + 1)))
        }
        return result
      }

      const descendants = await loadRecursive(rootChat)
      return [rootChat, ...descendants]
    },
    async loadUninitialized({ state }, chat) {
      if (!chat?.id) return null

      const storedChat = state.chats[chat.id]
      if (!storedChat) return null

      // Skip if already loaded or currently loading
      if (storedChat.status === 'loaded') {
        return storedChat
      }

      if (storedChat.status === 'loading') {
        // Chat is already loading, return it as-is
        return storedChat
      }

      // Load if uninitialized
      if (storedChat.status === 'uninitialized') {
        return await $storex.chats.loadChat(chat)
      }

      return storedChat
    },
    async saveChat({ state }, chat) {
      $storex.chats.setChatStatus({ chatId: chat.id, status: 'saving' })
      try {
        const project = getChatProject(chat)
        await project.$api.chats.save(chat)
        await $storex.chats.loadChat(chat)
        $storex.chats.setChatStatus({ chatId: chat.id, status: 'loaded' })
      } catch (error) {
        $storex.chats.setChatStatus({ chatId: chat.id, status: 'loaded' })
      }
    },
    async saveChatInfo(_, chat) {
      $storex.chats.setChatStatus({ chatId: chat.id, status: 'saving' })
      try {
        const project = getChatProject(chat)
        await project.$api.chats.saveChatInfo({ ...chat, messages: [] })
        await $storex.chats.loadChat(chat)
        $storex.chats.setChatStatus({ chatId: chat.id, status: 'loaded' })
      } catch (error) {
        $storex.chats.setChatStatus({ chatId: chat.id, status: 'loaded' })
      }
    },
    async findProjectChat({ state }, { id, owner_project_id }) {
      const project = $storex.projects.allProjectsById[owner_project_id]
      const chat = state.chats[id]
      if (chat) {
        return chat
      }
      const loadedChat = await project.$api.chats.loadChat({ id, owner_project_id })
      registerChat(state, loadedChat)
      return state.chats[id] || null
    },
    async loadChat({ state }, chat) {
      if (!state.chats[chat.id]) {
        const project = getChatProject(chat)
        $storex.chats.setChatStatus({ chatId: chat.id, status: 'loading' })
        try {
          const loadedChat = await project.$api.chats.loadChat(chat)
          registerChat(state, loadedChat)
          $storex.chats.setChatStatus({ chatId: chat.id, status: 'loaded' })
        } catch (error) {
          $storex.chats.setChatStatus({ chatId: chat.id, status: 'uninitialized' })
        }
      } else if (state.chats[chat.id].status === 'uninitialized') {
        const project = getChatProject(chat)
        $storex.chats.setChatStatus({ chatId: chat.id, status: 'loading' })
        try {
          const loadedChat = await project.$api.chats.loadChat(chat)
          registerChat(state, loadedChat)
          $storex.chats.setChatStatus({ chatId: chat.id, status: 'loaded' })
        } catch (error) {
          $storex.chats.setChatStatus({ chatId: chat.id, status: 'uninitialized' })
        }
      }
      return state.chats[chat.id]
    },
    async reloadChat({ state }, chat) {
      const project = getChatProject(chat)
      const freshChat = await project.$api.chats.loadChat(chat)
      if (freshChat && state.chats[chat.id]) {
        Object.assign(state.chats[chat.id], { ...freshChat, status: 'loaded' })
      } else {
        registerChat(state, { ...freshChat, status: 'loaded' })
      }
      return state.chats[chat.id]
    },
    async addMessage({ state }, { chat, message }) {
      if (!chat?.id) return

      const project = getChatProject(chat)

      // Generate doc_id immediately if missing
      if (!message.doc_id) {
        message.doc_id = uuidv4()
      }

      // Add to local state immediately (optimistic)
      $storex.chats.addMessageToChat({ chatId: chat.id, message })

      try {
        // Persist via API (merge-safe on backend)
        const updatedChat = await project.$api.chats.addMessage(chat.id, message)

        // Update local store with persisted version
        if (updatedChat && updatedChat.messages) {
          state.chats[chat.id].messages = updatedChat.messages
        }

        return updatedChat
      } catch (error) {
        console.error('[chats store] Failed to add message:', error)
        throw error
      }
    },
    async deleteChat({ state, getters }, chat) {
      if (!chat?.id) return

      const descendants = getters.chatDescendants(chat.id) || []

      if (!chat.temp) {
        const project = getChatProject(chat)
        await project.$api.chats.delete(chat)
      }

      const ids = new Set([chat.id, ...(descendants || []).map(c => c.id)])
      ids.forEach(id => {
        delete state.chats[id]
      })

      if (ids.has(state.activeChatId)) {
        $storex.chats.clearActiveChat()
      }
    },
    async setActiveChat({ state }, activeChat) {
      const { id, project_id, owner_project_id } = activeChat || {}

      if (!id) {
        $storex.chats.clearActiveChat()
        return
      }

      await $storex.chats.reloadChat({ id, project_id, owner_project_id })

      $storex.chats.setActiveChatId(id)

      if (!$storex.ui.isMobile && $storex.ui.viewMode !== 'vibe') {
        $storex.ui.openChat($storex.chats.activeChat)
      }
    },
    async createNewChat({ state }, chat) {
      chat = {
        id: uuidv4(),
        mode: 'chat',
        profiles: [],
        chat_index: 0,
        messages: [],
        auto_initialize: !chat.name,
        owner_project_id: chat.owner_project_id || $storex.projects.activeProject.project_id,
        status: 'uninitialized',
        ...chat
      }
      registerChat(state, chat)
      if (!chat.temp) {
        await $storex.chats.saveChat(chat)
      }
      return state.chats[chat.id]
    },
    async createNewChatWithProject({ state }, { project, chat = {} }) {
      const chatData = {
        ...chat,
        owner_project_id: project?.project_id || $storex.projects.activeProject.project_id
      }
      return await $storex.chats.createNewChat(chatData)
    },
    async createNewChatFromUrl({ state }, chat) {
      chat = {
        id: uuidv4(),
        mode: 'chat',
        profiles: [],
        chat_index: 0,
        status: 'uninitialized',
        ...chat
      }
      const project = getChatProject(chat)
      const savedChat = await project.$api.chats.fromUrl(chat)
      registerChat(state, { ...savedChat, status: 'loaded' })
      if (!chat.temp) {
        await $storex.chats.setActiveChat(savedChat)
      }
      return state.chats[savedChat?.id]
    },
    async createNewBoardChat({ state }, { boardTitle, columnTitle, chat }) {
      boardTitle = boardTitle || chat.board
      columnTitle = columnTitle || chat.column
      const newColumn = {
        title: columnTitle,
        chats: []
      }
      if (!$storex.projects.kanban) {
        await $storex.projects.loadKanban()
      }
      if (!$storex.projects.kanban.boards[boardTitle]) {
        $storex.projects.kanban.boards = {
          ...$storex.projects.kanban.boards,
          [boardTitle]: {
            columns: [newColumn]
          }
        }
      }
      let column = $storex.projects.allBoards
                        .find(({ title }) => title === boardTitle).columns.find(({ title }) => title === columnTitle)
      if (!column) {
        column = newColumn
        $storex.projects.kanban.boards[boardTitle].columns.push(column)
      }

      const newChat = await $storex.chats.createNewChat({
        board: boardTitle,
        column: columnTitle,
        ...chat
      })
      await $storex.chats.setActiveChat(newChat)
      column.chats = [...column?.chats || [], newChat.id]
      $storex.projects.saveKanban($storex.projects.kanban)
      return newChat
    },
    async createNewThread(_, { chat, mode, message }) {
      const { files, profiles, doc_id: subtaskMessageId } = message
      const findChild = $storex.chats.allChats.find(c => c.message_id === subtaskMessageId)

      if (!findChild) {
        const boardTitle = chat.board
        const columnTitle = chat.column
        await $storex.chats.createNewBoardChat({
          boardTitle, columnTitle,
          chat: {
            parent: chat,
            name: `${subtaskMessageId} - thread`,
            project_id: chat.project_id,
            parent_id: chat.parent_id,
            message_id: subtaskMessageId,
            file_list: files,
            profiles: profiles,
            mode,
            board: chat.board,
            column: chat.column,
            activateChat: true,
            messages: [{ ...message, doc_id: null }]
          }
        })
      } else {
        await $storex.chats.setActiveChat(findChild)
      }
    },
    async onChatEvent({ state }, { event, data }) {
      const {
        chat: {
          id: chatId,
          owner_project_id
        },
        message,
        event_type,
        type,
        codx_path
      } = data

      if (event_type === 'error') {
        $storex.ui.addNotification({ text: message, type: event_type })
      }

      if (chatId) {
        if (type === 'changed' || !state.chats[chatId]) {
          await $storex.chats.reloadChat({ id: chatId, owner_project_id })
        }
      }
    },
    async readFile({ state }, { chat, file }) {
      const project = getChatWorkingProject(chat)
      return project.$api.files.read(file)
    },
    async writeFile({ state }, { chat, file, content }) {
      const project = getChatWorkingProject(chat)
      return project.$api.files.write(file, content)
    }
  }
)

import { getterTree, mutationTree, actionTree } from 'typed-vuex'
import { $storex } from '.'

export const namespaced = true

const STORAGE_KEY_PREFIX = 'views'

export const state = () => ({
  views: [],
  currentView: null,
  lastView: null,
  // Desktop API and layout state owned here
  _desktopApi: null,
  _layoutChangeDisposable: null,
  _activePanelDisposable: null,
  fullscreenPanelId: null
})

export const getters = getterTree(state, {
  viewNames: state => state.views.map(v => v.name),
  hasViews: state => state.views.length > 0,
  currentViewName: state => state.currentView?.name || null,
  isPanelFullscreen: state => panelId => state.fullscreenPanelId === panelId,
})

export const mutations = mutationTree(state, {
  setViews(state, views) {
    state.views = views || []
  },
  setCurrentView(state, view) {
    state.currentView = view || null
  },
  setLastView(state, view) {
    state.lastView = view || null
  },
  upsertView(state, view) {
    const index = state.views.findIndex(v => v.name === view.name)
    if (index >= 0) {
      state.views.splice(index, 1, view)
    } else {
      state.views.push(view)
    }
  },
  removeView(state, viewName) {
    state.views = state.views.filter(v => v.name !== viewName)
  },
  // Desktop API registration - owned by views store
  setDesktopApi(state, api) {
    // Dispose previous layout change listener
    if (state._layoutChangeDisposable?.dispose) {
      state._layoutChangeDisposable.dispose()
      state._layoutChangeDisposable = null
    }

    // Dispose previous active panel listener
    if (state._activePanelDisposable?.dispose) {
      state._activePanelDisposable.dispose()
      state._activePanelDisposable = null
    }

    state._desktopApi = api

    if (api?.onDidLayoutChange) {
      state._layoutChangeDisposable = api.onDidLayoutChange(() => {
        $storex.views.saveCurrentView()
      })
    }

    // Listen for active panel changes to lazy-load chat if needed
    if (api?.onDidActivePanelChange) {
      state._activePanelDisposable = api.onDidActivePanelChange((event) => {
        $storex.views.onPanelActive(event)
      })
    }
  },
  setFullscreenPanel(state, panelId) {
    state.fullscreenPanelId = panelId
  },
  clearFullscreenPanel(state) {
    state.fullscreenPanelId = null
  }
})

// Helper - returns localStorage key scoped to active project
function getProjectStorageKey() {
  const projectName = $storex.projects?.activeProject?.project_name
  if (!projectName) return null
  return `${STORAGE_KEY_PREFIX}_${projectName}`
}

// Extract registered apps from a saved layout's panels structure
function extractAppsFromLayout(layout) {
  const apps = []
  if (!layout.panels) return apps

  for (const panel of Object.values(layout.panels)) {
    if (panel.params) {
      apps.push({
        tabId: panel.id || panel.tabId,
        name: panel.name || panel.componentName || 'Unknown',
        component: panel.componentName || 'unknown',
        key: panel.key,
        params: panel.params,
        openedAt: panel.openedAt || Date.now()
      })
    }
  }

  return apps
}

export const actions = actionTree(
  { state, getters, mutations },
  {
    async init() {
      await $storex.views.restoreLastProject()
    },

    async restoreLastProject() {
      try {
        const lastProjectId = localStorage.getItem('lastActiveProject')
        if (lastProjectId) {
          const project = $storex.projects.allProjects?.find(p => p.project_id === lastProjectId)
          if (project) {
            await $storex.projects.activeProjectChanged(project)
            return
          }
        }

        const defaultProject = $storex.projects.allProjects?.find(p => p.project_name === 'codx-junior')
        if (defaultProject) {
          await $storex.projects.activeProjectChanged(defaultProject)
        }
      } catch (error) {
        console.error('Failed to restore last project:', error)
      }
    },

    async loadViews() {
      if (!$storex.projects?.activeProject) return
      try {
        const key = getProjectStorageKey()
        if (!key) return

        const stored = localStorage.getItem(key)
        const gridData = stored ? JSON.parse(stored) : { views: [], currentView: null, lastView: null }

        $storex.views.setViews(gridData.views || [])

        const lastViewName = gridData.lastView
        if (lastViewName) {
          const lastView = gridData.views.find(v => v.name === lastViewName)
          if (lastView) {
            $storex.views.setLastView(lastView)
          }
        }
      } catch (error) {
        console.error('Failed to load views from localStorage:', error)
        $storex.views.setViews([])
      }
    },

    async onActiveProjectChanged() {
      $storex.views.setCurrentView(null)
      $storex.views.setLastView(null)
      await $storex.projects.saveLastActiveProject()
      await $storex.views.loadViews()
      await $storex.views.autoLoadLastView()
    },

    async autoLoadLastView({ state }) {
      const lastView = state.lastView
      if (!lastView?.layout) return

      try {
        if (!state._desktopApi) return
        await $storex.views.loadView(lastView)
      } catch (error) {
        console.error('Failed to auto-load last view:', error)
      }
    },

    async saveView({ state }, viewName) {
      try {
        const desktopApi = state._desktopApi
        if (!desktopApi) throw new Error('Desktop API not available')

        const layout = desktopApi.toJSON()
        const key = getProjectStorageKey()
        if (!key) throw new Error('No active project')

        const view = {
          name: viewName,
          layout,
          last_update: Date.now()
        }

        $storex.views.upsertView(view)
        await $storex.views.persistViews()
        $storex.views.setLastView(view)

        return view
      } catch (error) {
        console.error('Failed to save view:', error)
        throw error
      }
    },

    async loadView({ state }, view) {
      try {
        if (!view?.layout) throw new Error('Invalid view or layout')

        $storex.views.setCurrentView(view)
        $storex.views.setLastView(view)

        const desktopApi = state._desktopApi
        if (desktopApi) {
          desktopApi.fromJSON(view.layout)
          // Sync registered apps from restored layout into UI store
          await $storex.views.syncAppsFromLayout(view.layout)
        }
      } catch (error) {
        console.error('Failed to load view:', error)
        throw error
      }
    },

    async deleteView({ state }, viewName) {
      try {
        $storex.views.removeView(viewName)
        await $storex.views.persistViews()

        if (state.currentView?.name === viewName) {
          $storex.views.setCurrentView(null)
        }
        if (state.lastView?.name === viewName) {
          $storex.views.setLastView(null)
        }
      } catch (error) {
        console.error('Failed to delete view:', error)
        throw error
      }
    },

    async renameView({ state }, { oldName, newName }) {
      try {
        const existing = state.views.find(v => v.name === oldName)
        if (existing) {
          const renamedView = { ...existing, name: newName }
          $storex.views.removeView(oldName)
          $storex.views.upsertView(renamedView)

          if (state.currentView?.name === oldName) {
            $storex.views.setCurrentView(renamedView)
          }
          if (state.lastView?.name === oldName) {
            $storex.views.setLastView(renamedView)
          }

          await $storex.views.persistViews()
        }
      } catch (error) {
        console.error('Failed to rename view:', error)
        throw error
      }
    },

    async persistViews({ state }) {
      try {
        const key = getProjectStorageKey()
        if (!key) return

        const gridData = {
          views: state.views,
          currentView: state.currentView?.name || null,
          lastView: state.lastView?.name || null,
          lastUpdated: Date.now()
        }

        localStorage.setItem(key, JSON.stringify(gridData))
      } catch (error) {
        console.error('Failed to persist views to localStorage:', error)
        throw error
      }
    },

    async saveCurrentView({ state }) {
      try {
        const view = state.lastView || state.currentView
        if (!view?.name) return
        await $storex.views.saveView(view.name)
      } catch (error) {
        console.error('Error saving current view:', error)
      }
    },

    // Notify UI store of apps present in a layout so they appear as open
    async syncAppsFromLayout(_, layout) {
      try {
        const apps = extractAppsFromLayout(layout)
        for (const app of apps) {
          $storex.ui.showApp(app)
        }
      } catch (error) {
        console.error('Failed to sync apps from layout:', error)
      }
    },

    async restoreProjectLayout({ state }, desktopApi) {
      if (!desktopApi || !$storex.projects?.activeProject) {
        throw new Error('Desktop API or active project not available')
      }

      try {
        const key = getProjectStorageKey()
        if (!key) throw new Error('No active project storage key')

        const stored = localStorage.getItem(key)
        if (!stored) return false

        let gridData
        try {
          gridData = JSON.parse(stored)
        } catch (parseError) {
          console.error('Failed to parse stored layout:', parseError)
          return false
        }

        if (!gridData.views?.length) return false

        const lastViewName = gridData.lastView
        let layoutToRestore = null

        if (lastViewName) {
          const view = gridData.views.find(v => v.name === lastViewName)
          if (view?.layout) {
            layoutToRestore = view.layout
            $storex.views.setLastView(view)
          }
        }

        if (layoutToRestore) {
          desktopApi.fromJSON(layoutToRestore)
          await $storex.views.syncAppsFromLayout(layoutToRestore)
          return true
        }

        return false
      } catch (error) {
        console.error('Failed to restore project layout:', error)
        return false
      }
    },

    // Toggle fullscreen for a panel via the desktop API
    togglePanelFullscreen({ state }, panelId) {
      if (!state._desktopApi) return
      try {
        const panel = state._desktopApi.getPanel(panelId)
        if (panel) {
          state._desktopApi.maximizePanel(panel)
        }
      } catch(e) {
        console.error(`Error toggling fullscreen for panel ${panelId}:`, e)
      }
    },

    async onLayoutChanged({ state }) {
      try {
        const desktopApi = state._desktopApi
        if (!desktopApi) return

        const layout = desktopApi.toJSON()
        const key = getProjectStorageKey()
        if (!key) return

        if ($storex.views.lastView) {
          $storex.views.lastView.layout = layout
          $storex.views.lastView.last_update = Date.now()
          $storex.views.upsertView($storex.views.lastView)
        } else {
          const defaultView = {
            name: 'Default',
            layout,
            last_update: Date.now()
          }
          $storex.views.upsertView(defaultView)
          $storex.views.setLastView(defaultView)
        }

        await $storex.views.persistViews()
      } catch (error) {
        console.error('Error saving layout:', error)
      }
    },

    // Handles active panel change events from the desktop API - lazy-loads chats based on status
    async onPanelActive(_, event) {
      try {
        const panel = event?.panel
        if (!panel) return

        // Extract chat params from the panel - panels with chat component store chat in params
        const params = panel.params?.params || panel.params
        const chat = params?.chat
        if (!chat?.id) return

        // Use loadUninitialized to check status and load if needed
        await $storex.chats.loadUninitialized(chat)
      } catch (error) {
        console.error('Error handling active panel change:', error)
      }
    }
  }
)
